  F.territoryForZip = (state, zip) => {
    const z = String(zip).padStart(5, "0");
    const hit = F.zipTerritory.find(r => r[0] === state && z >= r[1] && z <= r[2]);
    return hit ? hit[3] : null;
  };
  F.lossCostFor = (state, territory, vehicleType, coverage) => {
    const r = F.liabLossCost.find(x => x[0] === state && x[1] === String(territory)
      && x[2] === vehicleType && x[3] === coverage);
    return r ? r[4] : null;
  };
  F.ilfFor = (state, ilta, limit) => {
    const r = F.ilf.find(x => x[0] === state && x[1] === String(ilta) && x[2] === limit);
    return r ? r[3] : null;
  };
  F.driverClassFor = (age, points) => {
    const r = F.driverClassFctr.find(x => x[0] === age && points >= x[1] && points <= x[2]);
    return r ? r[3] : null;
  };

  

